{
  "title": "神秘的遗书",
  "scene": "你在一座古老的图书馆内，四周堆满了灰尘和旧书。你发现了一本封皮破旧的日记，上面写着最后一位图书管理员的名字。你翻阅了几页，里面记录着一些奇怪的仪式和一本缺失的古籍。突然，你注意到日记的最后一页有一行用几乎看不见的墨水写的字：‘真正的秘密，在于不被人注意的地方。’",
  "goal": "找到图书馆的秘密",
  "clue": "日记最后一页的隐秘文字",
  "choices": [
    {
      "id": "A",
      "text": "仔细检查书架的角落",
      "outcome": "你在一个不起眼的角落发现了一个小机关，触动后，一扇隐藏的门缓缓打开，揭示了一个秘密房间。里面放着那本缺失的古籍。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "询问图书馆的工作人员",
      "outcome": "工作人员告诉你，图书馆的后门在几个月前被封了，里面什么都没有。虽然没有直接找到秘密，但你从对话中感受到了图书馆的历史和故事。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "按照日记中的仪式尝试",
      "outcome": "你尝试按照日记中的仪式进行，但似乎缺少了一些关键的步骤，最终仪式失败，你感到更加困惑和迷茫。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
